#include "hsa_backend.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void check(int rc) {
    if (rc) { fprintf(stderr, "%s\n", plow_hsa_last_error()); exit(1); }
}
static void* read_file(const char* path, size_t* bytes) {
    FILE* f = fopen(path, "rb"); assert(f);
    assert(!fseek(f, 0, SEEK_END)); *bytes = ftell(f); rewind(f);
    void* p = calloc(*bytes + 1, 1); assert(p);
    assert(fread(p, 1, *bytes, f) == *bytes); fclose(f); return p;
}
static void put64(uint8_t* args, size_t off, uint64_t value) { memcpy(args+off, &value, 8); }

int main(int argc, char** argv) {
    if (argc != 8) {
        fprintf(stderr, "usage: hsa ELF SYMBOL ARGS GRID NORMALIZED WEIGHT EXPECTED\n");
        return 2;
    }
    size_t eb, sb, ab, xb, wb, yb;
    void* elf = read_file(argv[1], &eb);
    char* symbol = read_file(argv[2], &sb);
    uint8_t* data = read_file(argv[3], &ab); assert(ab == 144);
    unsigned grid = strtoul(argv[4], 0, 10); assert(grid);
    void* x = read_file(argv[5], &xb); void* w = read_file(argv[6], &wb);
    void* expected = read_file(argv[7], &yb); assert(xb && wb && yb);
    plow_hsa* h = plow_hsa_init(); assert(h);
    char arch[64]; uint32_t cus, lds;
    check(plow_hsa_device_info(h, 0, arch, &cus, &lds));
    assert(!strcmp(arch,"gfx942") && cus == 304);
    check(plow_hsa_load_code_object(h, 0, elf, eb));
    plow_hsa_kernel kernel; check(plow_hsa_get_kernel(h, 0, symbol, &kernel));
    unsigned descriptor_bytes = kernel.kernarg_size;
    assert((descriptor_bytes == 0 || descriptor_bytes == 144) && kernel.private_segment_size == 0);
    kernel.kernarg_size = 144; kernel.kernarg_explicit = 144;
    void* hx = plow_hsa_alloc_host(h, xb); void* hw = plow_hsa_alloc_host(h, wb);
    uint8_t* hy = plow_hsa_alloc_host(h, yb + 512); assert(hx && hw && hy);
    memcpy(hx,x,xb); memcpy(hw,w,wb);
    void* dx = plow_hsa_alloc(h,0,xb); void* dw = plow_hsa_alloc(h,0,wb);
    void* dy = plow_hsa_alloc(h,0,yb+512); assert(dx && dw && dy);
    check(plow_hsa_copy_h2d(h,0,dx,hx,xb)); check(plow_hsa_copy_h2d(h,0,dw,hw,wb));
    put64(data,32,(uint64_t)dy); put64(data,40,(uint64_t)dy);
    put64(data,48,(uint64_t)dw); put64(data,56,(uint64_t)dx);
    for (unsigned reuse=0; reuse<3; ++reuse) {
        memset(hy,0x7f,yb+512); check(plow_hsa_copy_h2d(h,0,dy,hy,yb+512));
        check(plow_hsa_launch(h,0,&kernel,grid*256,1,1,256,1,1,0,data,144));
        check(plow_hsa_wait(h,0)); check(plow_hsa_copy_d2h(h,0,hy,dy,yb+512));
        assert(!memcmp(hy,expected,yb));
        for (size_t i=yb;i<yb+512;++i) assert(hy[i]==0x7f);
    }
    printf("{\"descriptor_bytes\":%u,\"argument_bytes\":144,\"lds_bytes\":%u,\"private_bytes\":%u,\"poisoned_reuses\":3,\"guard_bytes\":512,\"output_bytes\":%zu}\n", descriptor_bytes,kernel.group_segment_size,kernel.private_segment_size,yb);
    plow_hsa_free(h,dx); plow_hsa_free(h,dw); plow_hsa_free(h,dy);
    plow_hsa_free(h,hx); plow_hsa_free(h,hw); plow_hsa_free(h,hy); plow_hsa_shutdown(h);
    free(elf); free(symbol); free(data); free(x); free(w); free(expected);
    return 0;
}
